import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o,af as t}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"元宝术语表","description":"元宝、混元、CodeBuddy 不是同一个产品。","frontmatter":{"title":"元宝术语表","description":"元宝、混元、CodeBuddy 不是同一个产品。","domain":"product","tags":["chat"],"role":"explanation"},"headers":[],"relativePath":"zh/products/yuanbao/yuanbao-glossary.md","filePath":"zh/products/yuanbao/yuanbao-glossary.md","lastUpdated":1787107158000}'),r={name:"zh/products/yuanbao/yuanbao-glossary.md"};function s(d,a,p,l,i,h){return o(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="元宝术语表" tabindex="-1">元宝术语表 <a class="header-anchor" href="#元宝术语表" aria-label="Permalink to &quot;元宝术语表&quot;">​</a></h1><p>不教操作。只保证「元宝」两个字在本站口径一致。</p><h2 id="概念关系" tabindex="-1">概念关系 <a class="header-anchor" href="#概念关系" aria-label="Permalink to &quot;概念关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>腾讯</span></span>
<span class="line"><span>├── 元宝（助手产品，本目录）</span></span>
<span class="line"><span>│   └── 元宝派（产品内公测玩法）</span></span>
<span class="line"><span>├── 混元（模型 / 研究品牌，#77）</span></span>
<span class="line"><span>│   ├── Hy3（首页写「已接入」的模型名）</span></span>
<span class="line"><span>│   └── Hy AI Studio（混元站页脚）</span></span>
<span class="line"><span>├── CodeBuddy（编程助手，#78）</span></span>
<span class="line"><span>├── WorkBuddy（办公工作台，页脚）</span></span>
<span class="line"><span>└── ima（知识管家，页脚）</span></span></code></pre></div><h2 id="元宝" tabindex="-1">元宝 <a class="header-anchor" href="#元宝" aria-label="Permalink to &quot;元宝&quot;">​</a></h2><p><strong>是什么：</strong> 腾讯的消费级全能 AI 助手。官方英文名 Yuanbao。入口 <a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a>。</p><p><strong>为什么单独成页：</strong> 它是腾讯面向个人的聊天产品，和模型站、编程助手不是同一扇门。</p><p><strong>不是什么：</strong> 不是混元本身，不是 CodeBuddy，不是 CLI。</p><h2 id="混元-hy3" tabindex="-1">混元 / Hy3 <a class="header-anchor" href="#混元-hy3" aria-label="Permalink to &quot;混元 / Hy3&quot;">​</a></h2><p><strong>是什么：</strong> 腾讯的模型与研究品牌。站点 <a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a>。首页说元宝「已接入最新的混元 Hy3 模型」。</p><p><strong>与元宝的区别：</strong> 混元提供模型；元宝是其中一个消费产品。调用 API、下开源权重走混元站（#77），不要在元宝教程里教。</p><p>Play 商店简介仍出现「混元自研 T1 与 DeepSeek R1」。那是商店页原文，和首页 Hy3 文案并存。以客户端实际列表为准。</p><h2 id="元宝派" tabindex="-1">元宝派 <a class="header-anchor" href="#元宝派" aria-label="Permalink to &quot;元宝派&quot;">​</a></h2><p><strong>是什么：</strong> App Store / Play / 软件中心写在元宝特色里的玩法。原文含「开启公测，支持在元宝派养龙虾」。</p><p><strong>不是什么：</strong> 不是独立下载的第二个 App，也不是 WorkBuddy。</p><h2 id="codebuddy" tabindex="-1">CodeBuddy <a class="header-anchor" href="#codebuddy" aria-label="Permalink to &quot;CodeBuddy&quot;">​</a></h2><p><strong>是什么：</strong> 腾讯云代码助手。<a href="https://www.codebuddy.cn/" target="_blank" rel="noreferrer">codebuddy.cn</a>。本站 #78。</p><p><strong>与元宝「AI 编程」的区别：</strong> 元宝官方原文是对话里「无需部署」跑 Python / C++。CodeBuddy 才是编码工具产品。本目录只这一行。</p><h2 id="workbuddy" tabindex="-1">WorkBuddy <a class="header-anchor" href="#workbuddy" aria-label="Permalink to &quot;WorkBuddy&quot;">​</a></h2><p><strong>是什么：</strong> 混元首页页脚产品之一。官网自称「腾讯出品的全场景 AI 办公工作台」（<a href="https://www.workbuddy.cn/" target="_blank" rel="noreferrer">workbuddy.cn</a>）。</p><p><strong>不是什么：</strong> 不是元宝电脑版的别名。</p><h2 id="ima" tabindex="-1">ima <a class="header-anchor" href="#ima" aria-label="Permalink to &quot;ima&quot;">​</a></h2><p><strong>是什么：</strong> 混元首页页脚产品之一。官网：「ima 是以知识库为基础的AI知识管家」（<a href="https://ima.qq.com/" target="_blank" rel="noreferrer">ima.qq.com</a>）。</p><p><strong>不是什么：</strong> 不是元宝的「知识库模式」。</p><h2 id="hy-ai-studio" tabindex="-1">Hy AI Studio <a class="header-anchor" href="#hy-ai-studio" aria-label="Permalink to &quot;Hy AI Studio&quot;">​</a></h2><p><strong>是什么：</strong> 混元 <code>/solutions</code> 页脚里的产品项，和元宝、WorkBuddy 并列。用于在混元站试模型，不是元宝的一个 Tab。</p><h2 id="交付形态-协议里的词" tabindex="-1">交付形态（协议里的词） <a class="header-anchor" href="#交付形态-协议里的词" aria-label="Permalink to &quot;交付形态（协议里的词）&quot;">​</a></h2><p>用户服务协议把服务范围写成：网页、PC 客户端、小程序、浏览器插件，以及以后可能出现的形态。前两个有公开下载/网页入口；后两个 2026-08-19 没有找到独立官方安装页，术语上承认名字，教程里不写步骤。</p><h2 id="禁止写进正文的叫法" tabindex="-1">禁止写进正文的叫法 <a class="header-anchor" href="#禁止写进正文的叫法" aria-label="Permalink to &quot;禁止写进正文的叫法&quot;">​</a></h2><ul><li>「元宝 CLI」「Yuanbao Code」「元宝 IDE 插件」——官方页没有这些产品名。</li><li>把 <code>hunyuan.tencent.com/bot/chat</code> 叫成「混元聊天」——canonical 指向元宝。</li><li>把商店用户评论里的额度、价格、默认模型当成规格。</li></ul>`,30)])])}const m=n(r,[["render",s]]);export{g as __pageData,m as default};
